package com.sliverzfx.gothicquest

internal object RisenCommandData {
    val entries: List<ToolReferenceEntry> = listOf(part0(), part1(), part2()).flatten()

    private fun part0(): List<ToolReferenceEntry> = listOf(
        ToolReferenceEntry("r1_enable", "SETUP", "Enable the PC console", "During normal gameplay, type minsky quickly: finish insky within two seconds of m. Wait two seconds before retrying. This activates test mode. The original PC reference uses the caret key (^) to open the console; the physical key depends on keyboard layout. These commands target the original PC game, not the console ports.", command = "minsky", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_console", "SETUP", "Open the console", "After activating minsky, press the console key. Enter a command and press Enter. Use Tab to complete command names and supported parameters; repeated Tab presses cycle suggestions.", command = "^", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_help", "CONSOLE COMMANDS", "Console help", "Lists the console help available in your installed game.", command = "help", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_god", "CONSOLE COMMANDS", "God mode", "Enable invulnerability. Use god off to disable it.", command = "god on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_gold", "CONSOLE COMMANDS", "Add gold", "Adds 1,000 gold coins to your inventory. Replace 1000 with the desired quantity.", command = "give It_Gold 1000", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_give", "CONSOLE COMMANDS", "Give an item", "Replace <item> with an exact item ID and <amount> with a positive quantity. Adds it to inventory. Item cards below provide ready-to-copy examples. Giving a quest object does not reproduce the dialogue or quest events that normally award it.", command = "give <item> <amount>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_spawn", "CONSOLE COMMANDS", "Spawn an object or character", "Replace <entity> with the exact template ID. Creates it in front of the hero. A duplicate story character is not a replacement for the original quest state.", command = "spawn <entity>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_goto", "CONSOLE COMMANDS", "Teleport to an existing character", "Moves the hero to the first matching existing world object. Replace Inquisitor with another template, such as Doug. Objects inside inventories or containers cannot be reached this way.", command = "goto Inquisitor", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_invisible", "CONSOLE COMMANDS", "Hide from other characters", "Makes the hero ignored by other actors. Use invisible off to restore normal detection.", command = "invisible on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_teach", "CHARACTER EDITING", "Set a skill value", "Sets the named skill to the specified value; this is not normal trainer learning. This example sets learning points to 50. Individual attributes and skill IDs appear below.", command = "teach LP 50", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_time", "WORLD SETTINGS", "Set the game clock", "Sets the clock to 12:31. Use an hour followed by an optional minute, for example time 21.", command = "time 12 31", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_timescale", "WORLD SETTINGS", "Change time speed", "Sets the relationship between real time and game time. Replace 1 with another factor; 1 is the standard reference factor.", command = "timescale 1", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_defeat", "CONSOLE COMMANDS", "Defeat the focused enemy", "Knocks down the enemy currently in focus without using the kill command.", command = "defeat", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_kill", "CONSOLE COMMANDS", "Kill the focused enemy", "Kills the focused enemy. The game attributes the death to the hero, including experience and possible murder consequences.", command = "kill", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_edit", "CHARACTER EDITING", "Edit the focused object", "Opens the property editor for the focused object. Changes can affect actors and quest logic; keep an independent save before editing.", command = "edit", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_quest", "QUEST DEBUGGING", "Change a quest state", "Replace <quest> with its exact internal ID and <status> with open, run, cancel, close, succeed or fail. This changes the state flag; it does not execute every dialogue, reward or world event of a normal completion.", command = "setqueststatus <quest> <status>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_difficulty", "WORLD SETTINGS", "Set difficulty", "Select Easy, Normal or Hard. Ordinary difficulty settings are also available through the game menu.", command = "Difficulty Normal", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_autosave", "WORLD SETTINGS", "Enable autosaves", "Enables automatic saving. AutoSave off disables it. Keep manual saves for major decisions.", command = "AutoSave on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_firstperson", "CAMERA", "Experimental first-person camera", "Enables the unfinished first-person camera. FirstPersonCamera off disables it; visual or control glitches are possible.", command = "FirstPersonCamera on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_isometric", "CAMERA", "Experimental isometric camera", "Enables the experimental isometric camera. Use IsoCamera off to return.", command = "IsoCamera on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_fov", "CAMERA", "Free-camera field of view", "Replace <n> with a field-of-view value. Applies to the debug free camera.", command = "FreeCamFOV <n>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_camspeed", "CAMERA", "Free-camera movement speed", "Replace <n> with a movement-speed value for the debug free camera.", command = "FreeCamSpeed <n>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_camsprint", "CAMERA", "Free-camera sprint multiplier", "Replace <n> with the extra speed applied while using the free-camera sprint control.", command = "FreeCamSpeedModifier <n>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_camturn", "CAMERA", "Free-camera turning speed", "Replace <n> with the turning-speed factor for the debug free camera.", command = "FreeCamTurnSpeedFactor <n>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_endboss", "QUEST DEBUGGING", "Teleport to the final boss", "Moves straight to the final boss area. It does not equip the hero, unlock the normal route or complete prerequisite quests.", command = "EndBoss", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_benchmark", "DIAGNOSTICS", "Run the built-in benchmark", "Starts the rendering benchmark.", command = "benchmark", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_debug", "DIAGNOSTICS", "Show object debug information", "Shows diagnostic information about focused objects. DebugMode off disables it.", command = "DebugMode on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_screenshot", "DIAGNOSTICS", "Save a screenshot", "Replace <filename> with a screenshot filename.", command = "CameraDump <filename>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_statistics", "DIAGNOSTICS", "Dump statistics", "Replace <type> with a supported statistics type. This is a diagnostic command, not an item or attribute cheat.", command = "DumpStatistics <type>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_drawcalls", "DIAGNOSTICS", "Restore world rendering", "Turns rendering back on. ignoreDrawCalls on suppresses drawing and can leave the display black.", command = "ignoreDrawCalls off", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_mapedit", "WORLD DEBUGGING", "Edit a map template", "Replace both placeholders with valid identifiers. MapEdit remove <template> <map> removes a template. This edits world content and can disrupt a save.", command = "MapEdit insert <template> <map>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_music", "WORLD SETTINGS", "Set bandit-camp music", "Chooses the bandit-camp soundtrack context. Other documented locations include world and harbour. music daytime day or night changes the time context; music situation 0 or 1 changes the situation; music lock on or off controls automatic switching; music stop stops playback.", command = "music location doncamp", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_properties", "CHARACTER EDITING", "Modify an actor property", "Fill in the actor ID, property set, field and value. This is a low-level property edit; it can alter quest actors independently of their dialogue state.", command = "PS_modify <npc> <propertyset> <attribute> <value>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_config", "DIAGNOSTICS", "Set a configuration variable", "Replace <path> with a valid configuration variable path and its required parameters. There is no universal safe value.", command = "set <path>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_wind", "WORLD SETTINGS", "Change vegetation wind", "Replace the four placeholders with numeric wind parameters. Changes the vegetation wind simulation.", command = "SetVegWindParams <base> <factor> <bendweight> <wavespeed>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
    )

    private fun part1(): List<ToolReferenceEntry> = listOf(
        ToolReferenceEntry("r1_shaders", "GRAPHICS", "Shader quality", "Select Low, Medium or High.", command = "ShaderQuality High", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_shadows", "GRAPHICS", "Shadow quality", "Select Off, Low, Medium or High.", command = "ShadowQuality High", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_effects", "GRAPHICS", "Effect quality", "Select Low, Medium or High for shader effects.", command = "EffectQuality High", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_skeleton", "DIAGNOSTICS", "Display an actor skeleton", "Replace <entity> with an actor ID. Use off instead of on to hide its skeleton overlay.", command = "ShowSkeleton <entity> on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_softshadows", "GRAPHICS", "Soft shadows", "Enable soft shadows; use SoftShadows off to disable them.", command = "SoftShadows on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_ao", "GRAPHICS", "Ambient occlusion", "Enable screen-space ambient occlusion; use AmbientOcclusion off to disable it.", command = "AmbientOcclusion on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_speaker", "AUDIO", "Speaker mode", "Replace <mode> with a supported audio speaker configuration.", command = "SpeakerMode <mode>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_tutorial", "WORLD SETTINGS", "Tutorial popups", "Enable tutorial messages; use TutorialSystem off to disable them.", command = "TutorialSystem on", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_vegetation", "GRAPHICS", "Vegetation quality", "Select Off, Low, Medium or High.", command = "VegetationQuality High", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_weather", "WORLD SETTINGS", "Weather state", "Replace <state> with a weather state supported by your game. Use console completion to inspect available values.", command = "Weather <state>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_unknown", "DIAGNOSTICS", "Undocumented debug parameters", "The historical console reference also lists profile interval/queuesize, sector <name>, and teach LV <n>, but does not establish their effects. They are not recommended gameplay tools. The sector command is reported as potentially crash-prone.", command = null, source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_debug_keys", "SETUP", "Optional debug-key bindings", "The extra debug shortcuts are not active just because minsky is enabled. In the original PC configuration, define them in the Game / Controls / DebugKeys section of ConfigUser.xml under %LOCALAPPDATA%\\Risen. Back up the file before editing it and keep its XML structure intact. These are the historical binding names and input strings:\n\nOnDebugActionDefeat = CTRL_L+X\nOnDebugActionKill = CTRL_L+Y\nOnDebugActionKillWithForce = CTRL_L+C\nOnDebugAnimationCollisionMesh = CTRL_L+AE\nOnDebugAnimationSkeleton = CTRL_L+OE\nOnDebugAutoRunToggle = CTRL_L+O\nOnDebugBeamForward = CTRL_L+K\nOnDebugConnectPhysXDebugger = CTRL_L+P\nOnDebugControlFocusEntity = CTRL_L+F\nOnDebugCycleHeadNext = ALT_L+U\nOnDebugCycleHeadPrev = ALT_L+I\nOnDebugCycleHeadTexNext = ALT_L+J\nOnDebugCycleHeadTexPrev = ALT_L+K\nOnDebugCycleIndicators = F4\nOnDebugDumpPhysicsGroups = CTRL_L+UE\nOnDebugMovePlayerToCamera = CTRL_L+PAGE_UP\nOnDebugQuitApplication = F12\nOnDebugResetPlayer = F7\nOnDebugResetWithLift = CTRL_L+F8\nOnDebugTakeSnapshot = F1\nOnDebugToggleAudioEmitter = CTRL_L+A\nOnDebugToggleBoundingBoxes = CTRL_L+B\nOnDebugToggleCollisionShapes = CTRL_L+Q\nOnDebugToggleEntityInfos = CTRL_L+E\nOnDebugToggleFixedCam = CTRL_L+HOME\nOnDebugToggleFreeCam = NUM_8\nOnDebugToggleFreeFlyCam = CTRL_L+INSERT\nOnDebugToggleFullscreen = F2\nOnDebugToggleLevitate = CTRL_L+L\nOnDebugToggleMovementDebug = ALT_L+M\nOnDebugToggleNavigation = CTRL_L+N\nOnDebugToggleProfileLogging = ALT_L+L\nOnDebugToggleRaycasts = CTRL_L+R\nOnDebugToggleRenderMode = F3\nOnDebugToggleScreenMessages = CTRL_L+M\nOnDebugToggleSloMo = CTRL_L+F6\nOnDebugToggleSpeedTree = CTRL_L+T\nOnDebugToggleSpeedUp = F5\nOnDebugToggleStateGraphInfos = CTRL_L+G\nOnDebugToggleStatistics = CTRL_L+S\nOnDebugToggleTimeFreeze = PAUSE\nOnDebugToggleVegetation = CTRL_L+V\nOnDebug_ChangeResolution = CTRL_L+F2\nOnDebug_ToggleHUD = CTRL_L+H\nOnDebugSaySVM = ALT_L+S\n\nInput strings are configuration values, not console commands. Keyboard names and support may differ by release.", command = null, source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_key_beam", "CONFIGURED SHORTCUTS", "Move forward through obstacles", "Only after configuring OnDebugBeamForward = CTRL_L+K in ConfigUser.xml and activating minsky. Moves the hero forwards using the debug beam action. This is a key binding, not a command to enter in the console.", command = "CTRL_L+K", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_key_freecam", "CONFIGURED SHORTCUTS", "Toggle free camera", "Only after configuring OnDebugToggleFreeCam = NUM_8 in ConfigUser.xml and activating minsky. Toggles the debug free camera. This is a key binding, not a command to enter in the console.", command = "NUM_8", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_key_freefly", "CONFIGURED SHORTCUTS", "Toggle free-fly camera", "Only after configuring OnDebugToggleFreeFlyCam = CTRL_L+INSERT in ConfigUser.xml and activating minsky. Toggles the free-fly camera. This is a key binding, not a command to enter in the console.", command = "CTRL_L+INSERT", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_key_tocam", "CONFIGURED SHORTCUTS", "Move player to camera", "Only after configuring OnDebugMovePlayerToCamera = CTRL_L+PAGE_UP in ConfigUser.xml and activating minsky. Moves the player to the debug camera position. This is a key binding, not a command to enter in the console.", command = "CTRL_L+PAGE_UP", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_key_snapshot", "CONFIGURED SHORTCUTS", "Take a snapshot", "Only after configuring OnDebugTakeSnapshot = F1 in ConfigUser.xml and activating minsky. Triggers the configured debug snapshot action. This is a key binding, not a command to enter in the console.", command = "F1", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_key_hud", "CONFIGURED SHORTCUTS", "Toggle the HUD", "Only after configuring OnDebug_ToggleHUD = CTRL_L+H in ConfigUser.xml and activating minsky. Toggles the on-screen HUD. This is a key binding, not a command to enter in the console.", command = "CTRL_L+H", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_key_freeze", "CONFIGURED SHORTCUTS", "Freeze time", "Only after configuring OnDebugToggleTimeFreeze = PAUSE in ConfigUser.xml and activating minsky. Toggles the debug time-freeze action. This is a key binding, not a command to enter in the console.", command = "PAUSE", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_key_reset", "CONFIGURED SHORTCUTS", "Reset the player", "Only after configuring OnDebugResetPlayer = F7 in ConfigUser.xml and activating minsky. Triggers the player reset action; this is not a normal recovery method. This is a key binding, not a command to enter in the console.", command = "F7", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("r1_teach_Acrobat", "ATTRIBUTE & SKILL VALUES", "Set Acrobatics", "Internal field: Acrobat. Replaces this attribute or skill with the supplied value. Replace <value> with the desired value; this is not an additive bonus. Use normal skill ranges, and remember that editing a field does not complete faction training or quest dialogue.", command = "teach Acrobat <value>", source = "https://www.worldofrisen.de/risen/article_273.htm", codeCategory = CodeCategory.GENERAL),
